/*
 * ESP32-C3 SuperMini - Puente Transparente USB a UART LoRa
 * Utiliza GPIO 20 (RX) y GPIO 21 (TX) a 57600 bps.
 */

// Pines UART nativos del ESP32-C3 SuperMini
#define LORA_RX_PIN 20  // Conectar al pin TX del módulo LoRa
#define LORA_TX_PIN 21  // Conectar al pin RX del módulo LoRa

// Velocidad de transmisión requerida para el módulo LoRa
#define LORA_BAUD 57600 

void setup() {
  // Inicializa el puerto USB COM nativo hacia la PC
  Serial.begin(LORA_BAUD); 

  // Inicializa la UART física asociándola a los pines 20 y 21
  Serial1.begin(LORA_BAUD, SERIAL_8N1, LORA_RX_PIN, LORA_TX_PIN);

  // Espera a que el puerto USB virtual de la PC se estabilice
  delay(2000); 
  Serial.println("\n--- Puente Transparente USB-UART (Pines 20/21) Iniciado ---");
  Serial.print("Pines LoRa -> RX Físico: GPIO ");
  Serial.print(LORA_RX_PIN);
  Serial.print(" | TX Físico: GPIO ");
  Serial.println(LORA_TX_PIN);
}

void loop() {
  // 1. Recibe desde la PC (USB) y retransmite al módulo LoRa (GPIO 21)
  if (Serial.available()) {
    while (Serial.available()) {
      char c = Serial.read();
      Serial1.write(c); 
    }
  }

  // 2. Recibe desde el módulo LoRa (GPIO 20) y retransmite a la PC (USB)
  if (Serial1.available()) {
    while (Serial1.available()) {
      char c = Serial1.read();
      Serial.write(c); 
    }
  }
}
